corrected_code:
const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { PrescriptionRepository } = require('../repositories/prescription');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'pharmacy-spec.yaml'),
    validateRequests: true
  })
);

app.put('/api/v2/prescriptions/:prescriptionId/refill', async (req, res) => {
  if (!req.user || !req.user.prescriberNpi) {
    return res.status(401).json({ error: 'Prescriber credentials required' });
  }

  const { refillCount } = req.body;

  const prescription = await PrescriptionRepository.findById(req.params.prescriptionId);
  if (!prescription) {
    return res.status(404).json({ error: 'Prescription record not found' });
  }

  // Enforce that only the original prescriber or an authorized clinic partner can modify refills
  if (prescription.prescriberNpi !== req.user.prescriberNpi) {
    return res.status(403).json({ error: 'Access denied: caller is not the authorizing prescriber' });
  }

  prescription.authorizedRefills = refillCount;
  prescription.updatedAt = new Date();
  await prescription.save();

  res.json({ success: true, updatedPrescription: prescription });
});

app.listen(5002);
